outputs = ['yhgfwg', 'zgw', 'kdd', 'kxzai', 'fwgafwgkgh']

changed_pairs = []
for i in range(len(inputs)):
    if inputs[i] != outputs[i]:
        changed_pairs.append((i, inputs[i], outputs[i]))

print("Changed pairs:", changed_pairs)

# Now analyze each transformation
for idx, inp, outp in changed_pairs:
    print(f"Position {idx}: '{inp}' -> '{outp}'")

    # Find what's different
    if len(inp) <= len(outp):
        # Check for insertions
        for i in range(len(inp) + 1):
            if i == 0:
                prefix = ""
                suffix = inp
            else:
                prefix = inp[:i]
                suffix = inp[i:]

            # See if we can construct output from prefix + insertion + suffix
            if len(prefix) + 2 + len(suffix) == len(outp):
                # Try inserting two characters
                inserted = outp[len(prefix):len(prefix)+2]
                if prefix + inserted + suffix == outp:
                    print(f"  Insert '{inserted}' at position {i}")
                    break
    else:
        # Check for deletions
        pass

